import{_ as t,a as r,o as d,a6 as a}from"./chunks/framework.CJDy2q7X.js";const p=JSON.parse(`{"title":"Reopen a Return","description":"","frontmatter":{"outline":false,"examples":[{"id":"reopen-return","title":"Reopen a Return","description":"Reopen a canceled or declined return (RMA) request back to pending.","request":"POST /api/shop/returns/12/reopen\\nContent-Type: application/json\\nX-STOREFRONT-KEY: pk_storefront_PvlE42nWGsKRVIf8bDlJngTPAdWAZbIy\\nAuthorization: Bearer eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9...\\n","response":"{\\n  \\"id\\": 12,\\n  \\"orderId\\": 45,\\n  \\"orderIncrementId\\": \\"000000045\\",\\n  \\"statusId\\": 1,\\n  \\"statusTitle\\": \\"Pending\\",\\n  \\"statusColor\\": \\"#FDB022\\",\\n  \\"canClose\\": true,\\n  \\"canReopen\\": false,\\n  \\"isExpired\\": false,\\n  \\"messagesCount\\": 2,\\n  \\"updatedAt\\": \\"2026-07-20T11:05:00.000000Z\\"\\n}\\n","commonErrors":[{"error":"400 Bad Request","cause":"The store's settings do not allow reopening returns","solution":"Reopening must be enabled in the store's admin configuration"},{"error":"403 Forbidden","cause":"Missing or invalid customer Bearer token","solution":"Log in and provide a valid customer authentication token"},{"error":"401 Unauthorized","cause":"Storefront key is missing or invalid","solution":"Provide a valid X-STOREFRONT-KEY header"},{"error":"404 Not Found","cause":"The return does not exist or is not owned by the authenticated customer","solution":"Only return IDs belonging to the logged-in customer can be reopened"}]}]},"headers":[],"relativePath":"api/rest-api/shop/returns/reopen-return.md","filePath":"api/rest-api/shop/returns/reopen-return.md","lastUpdated":1786429091000}`),o={name:"api/rest-api/shop/returns/reopen-return.md"};function n(s,e,i,u,h,c){return d(),r("div",null,e[0]||(e[0]=[a('<h1 id="reopen-a-return" tabindex="-1">Reopen a Return <a class="header-anchor" href="#reopen-a-return" aria-label="Permalink to &quot;Reopen a Return&quot;">​</a></h1><p>Reopen a canceled or declined return (RMA) request back to <code>Pending</code> — but only when the store&#39;s settings allow customers to reopen returns. If reopening is disabled, the endpoint returns HTTP 400. The response carries the updated return.</p><h2 id="endpoint" tabindex="-1">Endpoint <a class="header-anchor" href="#endpoint" aria-label="Permalink to &quot;Endpoint&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>POST /api/shop/returns/{id}/reopen</span></span></code></pre></div><h2 id="authentication" tabindex="-1">Authentication <a class="header-anchor" href="#authentication" aria-label="Permalink to &quot;Authentication&quot;">​</a></h2><p>This endpoint requires an authenticated customer — send the storefront key and a customer Bearer token. See the <a href="/api/rest-api/authentication.html">Authentication</a> page.</p><h2 id="request-headers" tabindex="-1">Request Headers <a class="header-anchor" href="#request-headers" aria-label="Permalink to &quot;Request Headers&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Header</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>Content-Type</code></td><td>Yes</td><td>application/json</td></tr><tr><td><code>X-STOREFRONT-KEY</code></td><td>Yes</td><td>Your storefront API key</td></tr><tr><td><code>Authorization</code></td><td>Yes</td><td>Bearer token (customer login required)</td></tr></tbody></table><h2 id="path-parameters" tabindex="-1">Path Parameters <a class="header-anchor" href="#path-parameters" aria-label="Permalink to &quot;Path Parameters&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>integer</td><td>Yes</td><td>Id of the return to reopen. Must belong to the authenticated customer.</td></tr></tbody></table><h2 id="request-body" tabindex="-1">Request Body <a class="header-anchor" href="#request-body" aria-label="Permalink to &quot;Request Body&quot;">​</a></h2><p>No body is required — send an empty body.</p><h2 id="response-fields-200-ok" tabindex="-1">Response Fields (200 OK) <a class="header-anchor" href="#response-fields-200-ok" aria-label="Permalink to &quot;Response Fields (200 OK)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>integer</td><td>Return ID.</td></tr><tr><td><code>orderId</code></td><td>integer</td><td>Id of the order the item belongs to.</td></tr><tr><td><code>orderIncrementId</code></td><td>string</td><td>Human-readable order number.</td></tr><tr><td><code>statusId</code></td><td>integer</td><td>Numeric status id after the reopen — <code>1</code> (Pending).</td></tr><tr><td><code>statusTitle</code></td><td>string</td><td>Status label.</td></tr><tr><td><code>statusColor</code></td><td>string</td><td>Hex color for the status badge.</td></tr><tr><td><code>canClose</code></td><td>boolean</td><td>Whether the return can be closed.</td></tr><tr><td><code>canReopen</code></td><td>boolean</td><td>Whether the return can be reopened.</td></tr><tr><td><code>isExpired</code></td><td>boolean</td><td>Whether the return is past its action window.</td></tr><tr><td><code>messagesCount</code></td><td>integer</td><td>Number of conversation messages on the return.</td></tr><tr><td><code>updatedAt</code></td><td>string</td><td>ISO 8601 last update timestamp.</td></tr></tbody></table><h2 id="status-codes" tabindex="-1">Status Codes <a class="header-anchor" href="#status-codes" aria-label="Permalink to &quot;Status Codes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Status</th><th>Meaning</th></tr></thead><tbody><tr><td><code>200 OK</code></td><td>Return reopened.</td></tr><tr><td><code>400 Bad Request</code></td><td>Reopening is disabled in the store&#39;s settings.</td></tr><tr><td><code>401 Unauthorized</code></td><td>Missing or invalid storefront key.</td></tr><tr><td><code>403 Forbidden</code></td><td>Missing or invalid customer Bearer token.</td></tr><tr><td><code>404 Not Found</code></td><td>The return does not exist or is not the customer&#39;s.</td></tr></tbody></table><h2 id="related-resources" tabindex="-1">Related Resources <a class="header-anchor" href="#related-resources" aria-label="Permalink to &quot;Related Resources&quot;">​</a></h2><ul><li><a href="/api/rest-api/shop/returns/cancel-return.html">Cancel a Return</a> — withdraw a return the customer raised</li><li><a href="/api/rest-api/shop/returns/close-return.html">Close a Return</a> — mark a return solved</li><li><a href="/api/rest-api/shop/returns/">Returns Overview</a> — the returns menu overview, including the settings that gate it</li></ul>',18)]))}const b=t(o,[["render",n]]);export{p as __pageData,b as default};
